"use client";

import { forwardRef, type HTMLAttributes } from "react";
import { cn } from "@/lib/utils";

export interface TagProps extends HTMLAttributes<HTMLSpanElement> {
  variant?: "default" | "primary" | "genre" | "mood" | "instrument";
  size?: "sm" | "md";
  clickable?: boolean;
}

const Tag = forwardRef<HTMLSpanElement, TagProps>(
  (
    { className, variant = "default", size = "md", clickable = false, children, ...props },
    ref
  ) => {
    const variants = {
      default: "bg-[var(--color-cream)] text-[var(--color-black)]",
      primary: "bg-[var(--color-primary-light)] text-[var(--color-primary-dark)]",
      genre: "bg-[#DBEAFE] text-[#1E40AF]",
      mood: "bg-[#F3E8FF] text-[#6B21A8]",
      instrument: "bg-[#FEF3C7] text-[#92400E]",
    };

    const sizes = {
      sm: "px-2 py-0.5 text-xs",
      md: "px-3 py-1 text-sm",
    };

    return (
      <span
        ref={ref}
        className={cn(
          "inline-flex items-center font-medium border-2 border-[var(--color-black)] rounded-full transition-all duration-150",
          variants[variant],
          sizes[size],
          clickable &&
            "cursor-pointer hover:translate-x-[-1px] hover:translate-y-[-1px] hover:shadow-[2px_2px_0px_var(--color-black)] active:translate-x-0 active:translate-y-0 active:shadow-none",
          className
        )}
        {...props}
      >
        {children}
      </span>
    );
  }
);

Tag.displayName = "Tag";

export { Tag };

"use client";

import { cn } from "@/lib/utils";

interface SkeletonProps {
  className?: string;
}

export function Skeleton({ className }: SkeletonProps) {
  return (
    <div
      className={cn(
        "animate-pulse bg-[var(--color-gray-100)] rounded-[var(--radius-sm)]",
        className
      )}
    />
  );
}

export function AlbumCardSkeleton() {
  return (
    <div className="bg-[var(--color-white)] border-2 border-[var(--color-black)] rounded-[var(--radius-md)] shadow-[5px_5px_0px_var(--color-black)] overflow-hidden">
      <Skeleton className="aspect-square w-full rounded-none" />
      <div className="p-4 space-y-2">
        <Skeleton className="h-5 w-3/4" />
        <Skeleton className="h-4 w-1/2" />
      </div>
    </div>
  );
}

export function TrackRowSkeleton() {
  return (
    <div className="flex items-center gap-4 p-3 border-b border-[var(--color-gray-100)]">
      <Skeleton className="w-6 h-6" />
      <Skeleton className="w-10 h-10 rounded-[var(--radius-sm)]" />
      <div className="flex-1 space-y-2">
        <Skeleton className="h-4 w-1/3" />
        <Skeleton className="h-3 w-1/4" />
      </div>
      <Skeleton className="w-12 h-4" />
      <Skeleton className="w-16 h-4" />
    </div>
  );
}

export { Button, type ButtonProps } from "./Button";
export { Input, type InputProps } from "./Input";
export { Card, type CardProps } from "./Card";
export { Tag, type TagProps } from "./Tag";
export { Skeleton, AlbumCardSkeleton, TrackRowSkeleton } from "./Skeleton";

