"use client";

import { useState, useMemo } from "react";
import { motion } from "framer-motion";
import { Grid3X3, List, SlidersHorizontal } from "lucide-react";
import { Header, Footer } from "@/components/layout";
import { Button, Tag } from "@/components/ui";
import { AlbumCard, MiniPlayer } from "@/components/features";
import { mockAlbums, mockLabels, GENRES } from "@/lib/mock-data";
import { cn } from "@/lib/utils";
import type { ViewMode } from "@/types";

export default function AlbumsPage() {
  const [viewMode, setViewMode] = useState<ViewMode>("grid");
  const [selectedLabel, setSelectedLabel] = useState<string | null>(null);
  const [selectedGenre, setSelectedGenre] = useState<string | null>(null);
  const [showFilters, setShowFilters] = useState(false);

  const filteredAlbums = useMemo(() => {
    return mockAlbums.filter((album) => {
      if (selectedLabel && album.label !== selectedLabel) return false;
      if (selectedGenre && !album.genres.includes(selectedGenre)) return false;
      return true;
    });
  }, [selectedLabel, selectedGenre]);

  const uniqueLabels = useMemo(() => {
    return [...new Set(mockAlbums.map((a) => a.label))];
  }, []);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-1 py-8">
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
          {/* Page Header */}
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <div>
              <h1 className="text-3xl md:text-4xl font-bold text-[var(--color-black)]">
                Albums
              </h1>
              <p className="text-[var(--color-gray-600)] mt-1">
                {filteredAlbums.length} albums disponibles
              </p>
            </div>

            <div className="flex items-center gap-3">
              {/* Filter Toggle (Mobile) */}
              <Button
                variant="outline"
                size="sm"
                onClick={() => setShowFilters(!showFilters)}
                className="md:hidden gap-2"
              >
                <SlidersHorizontal size={16} />
                Filtres
              </Button>

              {/* View Toggle */}
              <div className="flex border-2 border-[var(--color-black)] rounded-[var(--radius-sm)] overflow-hidden">
                <button
                  onClick={() => setViewMode("grid")}
                  className={cn(
                    "p-2 transition-colors",
                    viewMode === "grid"
                      ? "bg-[var(--color-black)] text-white"
                      : "bg-white text-[var(--color-black)] hover:bg-[var(--color-gray-100)]"
                  )}
                >
                  <Grid3X3 size={18} />
                </button>
                <button
                  onClick={() => setViewMode("list")}
                  className={cn(
                    "p-2 transition-colors border-l-2 border-[var(--color-black)]",
                    viewMode === "list"
                      ? "bg-[var(--color-black)] text-white"
                      : "bg-white text-[var(--color-black)] hover:bg-[var(--color-gray-100)]"
                  )}
                >
                  <List size={18} />
                </button>
              </div>
            </div>
          </div>

          {/* Filters */}
          <div
            className={cn(
              "mb-8 space-y-4",
              showFilters ? "block" : "hidden md:block"
            )}
          >
            {/* Labels */}
            <div>
              <h3 className="text-sm font-semibold text-[var(--color-black)] mb-3">
                Labels
              </h3>
              <div className="flex flex-wrap gap-2">
                <Tag
                  variant={selectedLabel === null ? "primary" : "default"}
                  clickable
                  onClick={() => setSelectedLabel(null)}
                >
                  Tous
                </Tag>
                {uniqueLabels.map((label) => (
                  <Tag
                    key={label}
                    variant={selectedLabel === label ? "primary" : "default"}
                    clickable
                    onClick={() => setSelectedLabel(label)}
                  >
                    {label}
                  </Tag>
                ))}
              </div>
            </div>

            {/* Genres */}
            <div>
              <h3 className="text-sm font-semibold text-[var(--color-black)] mb-3">
                Genres
              </h3>
              <div className="flex flex-wrap gap-2">
                <Tag
                  variant={selectedGenre === null ? "primary" : "default"}
                  clickable
                  onClick={() => setSelectedGenre(null)}
                >
                  Tous
                </Tag>
                {GENRES.slice(0, 8).map((genre) => (
                  <Tag
                    key={genre}
                    variant={selectedGenre === genre ? "genre" : "default"}
                    clickable
                    onClick={() => setSelectedGenre(genre)}
                  >
                    {genre}
                  </Tag>
                ))}
              </div>
            </div>
          </div>

          {/* Albums Grid */}
          <div
            className={cn(
              "gap-4 md:gap-6",
              viewMode === "grid"
                ? "grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5"
                : "flex flex-col"
            )}
          >
            {filteredAlbums.map((album, index) => (
              <motion.div
                key={album.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: index * 0.05 }}
              >
                <AlbumCard album={album} />
              </motion.div>
            ))}
          </div>

          {/* Empty State */}
          {filteredAlbums.length === 0 && (
            <div className="text-center py-16">
              <p className="text-[var(--color-gray-600)] text-lg mb-4">
                Aucun album trouvé avec ces filtres.
              </p>
              <Button
                variant="outline"
                onClick={() => {
                  setSelectedLabel(null);
                  setSelectedGenre(null);
                }}
              >
                Réinitialiser les filtres
              </Button>
            </div>
          )}
        </div>
      </main>

      <Footer />
      <MiniPlayer />
    </div>
  );
}

"use client";

import { use } from "react";
import Image from "next/image";
import Link from "next/link";
import { motion } from "framer-motion";
import { Play, Heart, Share2, ArrowLeft, Clock, Music } from "lucide-react";
import { Header, Footer } from "@/components/layout";
import { Button, Tag, Card } from "@/components/ui";
import { TrackRow, AlbumCard, MiniPlayer } from "@/components/features";
import { getAlbumById, mockAlbums } from "@/lib/mock-data";
import { formatDuration } from "@/lib/utils";
import { usePlayerStore } from "@/stores/player-store";

interface AlbumPageProps {
  params: Promise<{ id: string }>;
}

export default function AlbumPage({ params }: AlbumPageProps) {
  const { id } = use(params);
  const album = getAlbumById(id);
  const { setQueue, play } = usePlayerStore();

  if (!album) {
    return (
      <div className="min-h-screen flex flex-col">
        <Header />
        <main className="flex-1 flex items-center justify-center">
          <div className="text-center">
            <h1 className="text-2xl font-bold mb-4">Album non trouvé</h1>
            <Link href="/albums">
              <Button variant="primary">Retour aux albums</Button>
            </Link>
          </div>
        </main>
        <Footer />
      </div>
    );
  }

  const totalDuration = album.tracks.reduce((acc, track) => acc + track.duration, 0);

  const handlePlayAll = () => {
    setQueue(album.tracks, 0);
    play(album.tracks[0]);
  };

  // Albums similaires (même genre)
  const similarAlbums = mockAlbums
    .filter(
      (a) =>
        a.id !== album.id &&
        a.genres.some((g) => album.genres.includes(g))
    )
    .slice(0, 4);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-1 pb-24">
        {/* Back Link */}
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-4">
          <Link
            href="/albums"
            className="inline-flex items-center gap-2 text-[var(--color-gray-600)] hover:text-[var(--color-black)] transition-colors"
          >
            <ArrowLeft size={18} />
            Retour aux albums
          </Link>
        </div>

        {/* Album Header */}
        <section className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-8">
          <div className="flex flex-col md:flex-row gap-8">
            {/* Cover */}
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              className="w-full md:w-80 flex-shrink-0"
            >
              <Card padding="none" className="overflow-hidden aspect-square relative">
                <Image
                  src={album.cover}
                  alt={album.title}
                  fill
                  sizes="(max-width: 768px) 100vw, 320px"
                  className="object-cover"
                  priority
                />
              </Card>
            </motion.div>

            {/* Info */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className="flex-1"
            >
              <p className="text-sm font-medium text-[var(--color-primary)] mb-2">
                {album.label}
              </p>
              <h1 className="text-3xl md:text-4xl lg:text-5xl font-bold text-[var(--color-black)] mb-4">
                {album.title}
              </h1>
              <p className="text-[var(--color-gray-600)] mb-6 max-w-xl">
                {album.description}
              </p>

              {/* Meta */}
              <div className="flex flex-wrap items-center gap-4 text-sm text-[var(--color-gray-600)] mb-6">
                <span className="flex items-center gap-1">
                  <Music size={16} />
                  {album.trackCount} pistes
                </span>
                <span className="flex items-center gap-1">
                  <Clock size={16} />
                  {formatDuration(totalDuration)}
                </span>
                <span>
                  Sorti le {new Date(album.releaseDate).toLocaleDateString("fr-FR")}
                </span>
              </div>

              {/* Tags */}
              <div className="flex flex-wrap gap-2 mb-8">
                {album.genres.map((genre) => (
                  <Link key={genre} href={`/search?genre=${genre}`}>
                    <Tag variant="genre" clickable>
                      {genre}
                    </Tag>
                  </Link>
                ))}
                {album.moods.map((mood) => (
                  <Link key={mood} href={`/search?mood=${mood}`}>
                    <Tag variant="mood" clickable>
                      {mood}
                    </Tag>
                  </Link>
                ))}
              </div>

              {/* Actions */}
              <div className="flex flex-wrap gap-3">
                <Button variant="primary" size="lg" onClick={handlePlayAll}>
                  <Play size={20} className="mr-2 fill-white" />
                  Tout écouter
                </Button>
                <Button variant="outline" size="lg">
                  <Heart size={20} className="mr-2" />
                  Favoris
                </Button>
                <Button variant="ghost" size="lg">
                  <Share2 size={20} />
                </Button>
              </div>
            </motion.div>
          </div>
        </section>

        {/* Tracks */}
        <section className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-8">
          <h2 className="text-xl font-bold text-[var(--color-black)] mb-6">
            Pistes
          </h2>
          <Card padding="none" className="divide-y divide-[var(--color-gray-100)]">
            {album.tracks.map((track, index) => (
              <TrackRow
                key={track.id}
                track={track}
                album={album}
                index={index}
                showAlbumCover={false}
              />
            ))}
          </Card>
        </section>

        {/* Similar Albums */}
        {similarAlbums.length > 0 && (
          <section className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-8">
            <h2 className="text-xl font-bold text-[var(--color-black)] mb-6">
              Albums similaires
            </h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6">
              {similarAlbums.map((similarAlbum, index) => (
                <motion.div
                  key={similarAlbum.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.1 }}
                >
                  <AlbumCard album={similarAlbum} />
                </motion.div>
              ))}
            </div>
          </section>
        )}
      </main>

      <Footer />
      <MiniPlayer />
    </div>
  );
}

"use client";

import { useState, useMemo, useCallback, Suspense } from "react";
import { useSearchParams } from "next/navigation";
import { motion } from "framer-motion";
import {
  Grid3X3,
  List,
  X,
  ChevronDown,
  ChevronUp,
  RotateCcw,
} from "lucide-react";
import { Header, Footer } from "@/components/layout";
import { Button, Tag, Card, Input } from "@/components/ui";
import { TrackRow, SearchBar, MiniPlayer } from "@/components/features";
import {
  getAllTracks,
  mockAlbums,
  GENRES,
  MOODS,
  INSTRUMENTS,
} from "@/lib/mock-data";
import { cn } from "@/lib/utils";
import type { ViewMode, Track } from "@/types";

function SearchContent() {
  const searchParams = useSearchParams();
  const initialQuery = searchParams.get("q") || "";
  const initialGenre = searchParams.get("genre") || "";
  const initialMood = searchParams.get("mood") || "";

  const [query, setQuery] = useState(initialQuery);
  const [viewMode, setViewMode] = useState<ViewMode>("list");
  const [showFilters, setShowFilters] = useState(true);

  // Filter states
  const [selectedGenres, setSelectedGenres] = useState<string[]>(
    initialGenre ? [initialGenre] : []
  );
  const [selectedMoods, setSelectedMoods] = useState<string[]>(
    initialMood ? [initialMood] : []
  );
  const [selectedInstruments, setSelectedInstruments] = useState<string[]>([]);
  const [bpmRange, setBpmRange] = useState<[number, number]>([60, 180]);
  const [durationRange, setDurationRange] = useState<[number, number]>([0, 300]);
  const [isVocal, setIsVocal] = useState<boolean | null>(null);

  // Collapsed sections
  const [collapsedSections, setCollapsedSections] = useState<Set<string>>(
    new Set()
  );

  const toggleSection = (section: string) => {
    setCollapsedSections((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(section)) {
        newSet.delete(section);
      } else {
        newSet.add(section);
      }
      return newSet;
    });
  };

  const allTracks = getAllTracks();

  const filteredTracks = useMemo(() => {
    return allTracks.filter((track) => {
      // Text search
      if (query) {
        const lowerQuery = query.toLowerCase();
        const album = mockAlbums.find((a) => a.id === track.albumId);
        const matchesTitle = track.title.toLowerCase().includes(lowerQuery);
        const matchesAlbum = album?.title.toLowerCase().includes(lowerQuery);
        const matchesGenre = track.genres.some((g) =>
          g.toLowerCase().includes(lowerQuery)
        );
        const matchesMood = track.moods.some((m) =>
          m.toLowerCase().includes(lowerQuery)
        );
        if (!matchesTitle && !matchesAlbum && !matchesGenre && !matchesMood) {
          return false;
        }
      }

      // Genres
      if (
        selectedGenres.length > 0 &&
        !selectedGenres.some((g) => track.genres.includes(g))
      ) {
        return false;
      }

      // Moods
      if (
        selectedMoods.length > 0 &&
        !selectedMoods.some((m) => track.moods.includes(m))
      ) {
        return false;
      }

      // Instruments
      if (
        selectedInstruments.length > 0 &&
        !selectedInstruments.some((i) => track.instruments.includes(i))
      ) {
        return false;
      }

      // BPM
      if (track.bpm < bpmRange[0] || track.bpm > bpmRange[1]) {
        return false;
      }

      // Duration
      if (track.duration < durationRange[0] || track.duration > durationRange[1]) {
        return false;
      }

      // Vocal
      if (isVocal !== null && track.isVocal !== isVocal) {
        return false;
      }

      return true;
    });
  }, [
    allTracks,
    query,
    selectedGenres,
    selectedMoods,
    selectedInstruments,
    bpmRange,
    durationRange,
    isVocal,
  ]);

  const resetFilters = useCallback(() => {
    setQuery("");
    setSelectedGenres([]);
    setSelectedMoods([]);
    setSelectedInstruments([]);
    setBpmRange([60, 180]);
    setDurationRange([0, 300]);
    setIsVocal(null);
  }, []);

  const hasActiveFilters =
    query ||
    selectedGenres.length > 0 ||
    selectedMoods.length > 0 ||
    selectedInstruments.length > 0 ||
    bpmRange[0] !== 60 ||
    bpmRange[1] !== 180 ||
    durationRange[0] !== 0 ||
    durationRange[1] !== 300 ||
    isVocal !== null;

  const toggleArrayFilter = (
    arr: string[],
    setArr: (arr: string[]) => void,
    value: string
  ) => {
    if (arr.includes(value)) {
      setArr(arr.filter((v) => v !== value));
    } else {
      setArr([...arr, value]);
    }
  };

  const FilterSection = ({
    title,
    id,
    children,
  }: {
    title: string;
    id: string;
    children: React.ReactNode;
  }) => {
    const isCollapsed = collapsedSections.has(id);
    return (
      <div className="border-b border-[var(--color-gray-100)] pb-4">
        <button
          onClick={() => toggleSection(id)}
          className="flex items-center justify-between w-full py-2 text-left"
        >
          <span className="font-semibold text-[var(--color-black)]">{title}</span>
          {isCollapsed ? <ChevronDown size={18} /> : <ChevronUp size={18} />}
        </button>
        {!isCollapsed && <div className="mt-2">{children}</div>}
      </div>
    );
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-1 pb-24">
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-8">
          {/* Search Bar */}
          <div className="mb-8">
            <SearchBar
              defaultValue={query}
              onSearch={setQuery}
              placeholder="Rechercher par titre, genre, mood..."
            />
          </div>

          <div className="flex flex-col lg:flex-row gap-8">
            {/* Filters Sidebar */}
            <aside
              className={cn(
                "lg:w-72 flex-shrink-0",
                showFilters ? "block" : "hidden lg:block"
              )}
            >
              <Card padding="md" hover={false}>
                <div className="flex items-center justify-between mb-4">
                  <h2 className="font-bold text-[var(--color-black)]">Filtres</h2>
                  {hasActiveFilters && (
                    <button
                      onClick={resetFilters}
                      className="text-sm text-[var(--color-primary)] hover:underline flex items-center gap-1"
                    >
                      <RotateCcw size={14} />
                      Réinitialiser
                    </button>
                  )}
                </div>

                <div className="space-y-4">
                  {/* Genres */}
                  <FilterSection title="Genres" id="genres">
                    <div className="flex flex-wrap gap-2">
                      {GENRES.map((genre) => (
                        <Tag
                          key={genre}
                          variant={
                            selectedGenres.includes(genre) ? "genre" : "default"
                          }
                          size="sm"
                          clickable
                          onClick={() =>
                            toggleArrayFilter(
                              selectedGenres,
                              setSelectedGenres,
                              genre
                            )
                          }
                        >
                          {genre}
                          {selectedGenres.includes(genre) && (
                            <X size={12} className="ml-1" />
                          )}
                        </Tag>
                      ))}
                    </div>
                  </FilterSection>

                  {/* Moods */}
                  <FilterSection title="Moods" id="moods">
                    <div className="flex flex-wrap gap-2">
                      {MOODS.map((mood) => (
                        <Tag
                          key={mood}
                          variant={
                            selectedMoods.includes(mood) ? "mood" : "default"
                          }
                          size="sm"
                          clickable
                          onClick={() =>
                            toggleArrayFilter(
                              selectedMoods,
                              setSelectedMoods,
                              mood
                            )
                          }
                        >
                          {mood}
                          {selectedMoods.includes(mood) && (
                            <X size={12} className="ml-1" />
                          )}
                        </Tag>
                      ))}
                    </div>
                  </FilterSection>

                  {/* Instruments */}
                  <FilterSection title="Instruments" id="instruments">
                    <div className="flex flex-wrap gap-2">
                      {INSTRUMENTS.map((instrument) => (
                        <Tag
                          key={instrument}
                          variant={
                            selectedInstruments.includes(instrument)
                              ? "instrument"
                              : "default"
                          }
                          size="sm"
                          clickable
                          onClick={() =>
                            toggleArrayFilter(
                              selectedInstruments,
                              setSelectedInstruments,
                              instrument
                            )
                          }
                        >
                          {instrument}
                          {selectedInstruments.includes(instrument) && (
                            <X size={12} className="ml-1" />
                          )}
                        </Tag>
                      ))}
                    </div>
                  </FilterSection>

                  {/* BPM Range */}
                  <FilterSection title="Tempo (BPM)" id="bpm">
                    <div className="space-y-2">
                      <div className="flex items-center gap-2">
                        <Input
                          type="number"
                          value={bpmRange[0]}
                          onChange={(e) =>
                            setBpmRange([parseInt(e.target.value) || 60, bpmRange[1]])
                          }
                          className="w-20 text-sm py-1 px-2"
                          min={60}
                          max={180}
                        />
                        <span className="text-[var(--color-gray-400)]">-</span>
                        <Input
                          type="number"
                          value={bpmRange[1]}
                          onChange={(e) =>
                            setBpmRange([bpmRange[0], parseInt(e.target.value) || 180])
                          }
                          className="w-20 text-sm py-1 px-2"
                          min={60}
                          max={180}
                        />
                      </div>
                    </div>
                  </FilterSection>

                  {/* Vocal/Instrumental */}
                  <FilterSection title="Type" id="vocal">
                    <div className="flex gap-2">
                      <Tag
                        variant={isVocal === null ? "primary" : "default"}
                        size="sm"
                        clickable
                        onClick={() => setIsVocal(null)}
                      >
                        Tous
                      </Tag>
                      <Tag
                        variant={isVocal === true ? "primary" : "default"}
                        size="sm"
                        clickable
                        onClick={() => setIsVocal(true)}
                      >
                        Vocal
                      </Tag>
                      <Tag
                        variant={isVocal === false ? "primary" : "default"}
                        size="sm"
                        clickable
                        onClick={() => setIsVocal(false)}
                      >
                        Instrumental
                      </Tag>
                    </div>
                  </FilterSection>
                </div>
              </Card>
            </aside>

            {/* Results */}
            <div className="flex-1">
              {/* Results Header */}
              <div className="flex items-center justify-between mb-4">
                <p className="text-[var(--color-gray-600)]">
                  <span className="font-semibold text-[var(--color-black)]">
                    {filteredTracks.length}
                  </span>{" "}
                  résultats
                </p>

                <div className="flex items-center gap-3">
                  {/* Mobile Filter Toggle */}
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setShowFilters(!showFilters)}
                    className="lg:hidden"
                  >
                    Filtres
                  </Button>

                  {/* View Toggle */}
                  <div className="flex border-2 border-[var(--color-black)] rounded-[var(--radius-sm)] overflow-hidden">
                    <button
                      onClick={() => setViewMode("list")}
                      className={cn(
                        "p-2 transition-colors",
                        viewMode === "list"
                          ? "bg-[var(--color-black)] text-white"
                          : "bg-white text-[var(--color-black)] hover:bg-[var(--color-gray-100)]"
                      )}
                    >
                      <List size={18} />
                    </button>
                    <button
                      onClick={() => setViewMode("grid")}
                      className={cn(
                        "p-2 transition-colors border-l-2 border-[var(--color-black)]",
                        viewMode === "grid"
                          ? "bg-[var(--color-black)] text-white"
                          : "bg-white text-[var(--color-black)] hover:bg-[var(--color-gray-100)]"
                      )}
                    >
                      <Grid3X3 size={18} />
                    </button>
                  </div>
                </div>
              </div>

              {/* Active Filters */}
              {hasActiveFilters && (
                <div className="flex flex-wrap gap-2 mb-4">
                  {selectedGenres.map((genre) => (
                    <Tag
                      key={genre}
                      variant="genre"
                      size="sm"
                      clickable
                      onClick={() =>
                        setSelectedGenres(selectedGenres.filter((g) => g !== genre))
                      }
                    >
                      {genre}
                      <X size={12} className="ml-1" />
                    </Tag>
                  ))}
                  {selectedMoods.map((mood) => (
                    <Tag
                      key={mood}
                      variant="mood"
                      size="sm"
                      clickable
                      onClick={() =>
                        setSelectedMoods(selectedMoods.filter((m) => m !== mood))
                      }
                    >
                      {mood}
                      <X size={12} className="ml-1" />
                    </Tag>
                  ))}
                </div>
              )}

              {/* Track List */}
              {filteredTracks.length > 0 ? (
                <Card padding="none" hover={false}>
                  {filteredTracks.slice(0, 50).map((track, index) => {
                    const album = mockAlbums.find((a) => a.id === track.albumId);
                    return (
                      <TrackRow
                        key={track.id}
                        track={track}
                        album={album}
                        index={index}
                        showAlbumCover={true}
                      />
                    );
                  })}
                </Card>
              ) : (
                <div className="text-center py-16">
                  <p className="text-[var(--color-gray-600)] text-lg mb-4">
                    Aucune piste trouvée avec ces critères.
                  </p>
                  <Button variant="outline" onClick={resetFilters}>
                    Réinitialiser les filtres
                  </Button>
                </div>
              )}

              {filteredTracks.length > 50 && (
                <p className="text-center text-[var(--color-gray-400)] mt-4">
                  Affichage des 50 premiers résultats sur {filteredTracks.length}
                </p>
              )}
            </div>
          </div>
        </div>
      </main>

      <Footer />
      <MiniPlayer />
    </div>
  );
}

export default function SearchPage() {
  return (
    <Suspense fallback={<div>Chargement...</div>}>
      <SearchContent />
    </Suspense>
  );
}

toolUseResult.content:
"use client";

import { useState, useMemo } from "react";
import { motion } from "framer-motion";
import { Grid3X3, List, SlidersHorizontal } from "lucide-react";
import { Header, Footer } from "@/components/layout";
import { Button, Tag } from "@/components/ui";
import { AlbumCard, MiniPlayer } from "@/components/features";
import { mockAlbums, mockLabels, GENRES } from "@/lib/mock-data";
import { cn } from "@/lib/utils";
import type { ViewMode } from "@/types";

export default function AlbumsPage() {
  const [viewMode, setViewMode] = useState<ViewMode>("grid");
  const [selectedLabel, setSelectedLabel] = useState<string | null>(null);
  const [selectedGenre, setSelectedGenre] = useState<string | null>(null);
  const [showFilters, setShowFilters] = useState(false);

  const filteredAlbums = useMemo(() => {
    return mockAlbums.filter((album) => {
      if (selectedLabel && album.label !== selectedLabel) return false;
      if (selectedGenre && !album.genres.includes(selectedGenre)) return false;
      return true;
    });
  }, [selectedLabel, selectedGenre]);

  const uniqueLabels = useMemo(() => {
    return [...new Set(mockAlbums.map((a) => a.label))];
  }, []);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-1 py-8">
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
          {/* Page Header */}
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <div>
              <h1 className="text-3xl md:text-4xl font-bold text-[var(--color-black)]">
                Albums
              </h1>
              <p className="text-[var(--color-gray-600)] mt-1">
                {filteredAlbums.length} albums disponibles
              </p>
            </div>

            <div className="flex items-center gap-3">
              {/* Filter Toggle (Mobile) */}
              <Button
                variant="outline"
                size="sm"
                onClick={() => setShowFilters(!showFilters)}
                className="md:hidden gap-2"
              >
                <SlidersHorizontal size={16} />
                Filtres
              </Button>

              {/* View Toggle */}
              <div className="flex border-2 border-[var(--color-black)] rounded-[var(--radius-sm)] overflow-hidden">
                <button
                  onClick={() => setViewMode("grid")}
                  className={cn(
                    "p-2 transition-colors",
                    viewMode === "grid"
                      ? "bg-[var(--color-black)] text-white"
                      : "bg-white text-[var(--color-black)] hover:bg-[var(--color-gray-100)]"
                  )}
                >
                  <Grid3X3 size={18} />
                </button>
                <button
                  onClick={() => setViewMode("list")}
                  className={cn(
                    "p-2 transition-colors border-l-2 border-[var(--color-black)]",
                    viewMode === "list"
                      ? "bg-[var(--color-black)] text-white"
                      : "bg-white text-[var(--color-black)] hover:bg-[var(--color-gray-100)]"
                  )}
                >
                  <List size={18} />
                </button>
              </div>
            </div>
          </div>

          {/* Filters */}
          <div
            className={cn(
              "mb-8 space-y-4",
              showFilters ? "block" : "hidden md:block"
            )}
          >
            {/* Labels */}
            <div>
              <h3 className="text-sm font-semibold text-[var(--color-black)] mb-3">
                Labels
              </h3>
              <div className="flex flex-wrap gap-2">
                <Tag
                  variant={selectedLabel === null ? "primary" : "default"}
                  clickable
                  onClick={() => setSelectedLabel(null)}
                >
                  Tous
                </Tag>
                {uniqueLabels.map((label) => (
                  <Tag
                    key={label}
                    variant={selectedLabel === label ? "primary" : "default"}
                    clickable
                    onClick={() => setSelectedLabel(label)}
                  >
                    {label}
                  </Tag>
                ))}
              </div>
            </div>

            {/* Genres */}
            <div>
              <h3 className="text-sm font-semibold text-[var(--color-black)] mb-3">
                Genres
              </h3>
              <div className="flex flex-wrap gap-2">
                <Tag
                  variant={selectedGenre === null ? "primary" : "default"}
                  clickable
                  onClick={() => setSelectedGenre(null)}
                >
                  Tous
                </Tag>
                {GENRES.slice(0, 8).map((genre) => (
                  <Tag
                    key={genre}
                    variant={selectedGenre === genre ? "genre" : "default"}
                    clickable
                    onClick={() => setSelectedGenre(genre)}
                  >
                    {genre}
                  </Tag>
                ))}
              </div>
            </div>
          </div>

          {/* Albums Grid */}
          <div
            className={cn(
              "gap-4 md:gap-6",
              viewMode === "grid"
                ? "grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5"
                : "flex flex-col"
            )}
          >
            {filteredAlbums.map((album, index) => (
              <motion.div
                key={album.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: index * 0.05 }}
              >
                <AlbumCard album={album} />
              </motion.div>
            ))}
          </div>

          {/* Empty State */}
          {filteredAlbums.length === 0 && (
            <div className="text-center py-16">
              <p className="text-[var(--color-gray-600)] text-lg mb-4">
                Aucun album trouvé avec ces filtres.
              </p>
              <Button
                variant="outline"
                onClick={() => {
                  setSelectedLabel(null);
                  setSelectedGenre(null);
                }}
              >
                Réinitialiser les filtres
              </Button>
            </div>
          )}
        </div>
      </main>

      <Footer />
      <MiniPlayer />
    </div>
  );
}

"use client";

import { use } from "react";
import Image from "next/image";
import Link from "next/link";
import { motion } from "framer-motion";
import { Play, Heart, Share2, ArrowLeft, Clock, Music } from "lucide-react";
import { Header, Footer } from "@/components/layout";
import { Button, Tag, Card } from "@/components/ui";
import { TrackRow, AlbumCard, MiniPlayer } from "@/components/features";
import { getAlbumById, mockAlbums } from "@/lib/mock-data";
import { formatDuration } from "@/lib/utils";
import { usePlayerStore } from "@/stores/player-store";

interface AlbumPageProps {
  params: Promise<{ id: string }>;
}

export default function AlbumPage({ params }: AlbumPageProps) {
  const { id } = use(params);
  const album = getAlbumById(id);
  const { setQueue, play } = usePlayerStore();

  if (!album) {
    return (
      <div className="min-h-screen flex flex-col">
        <Header />
        <main className="flex-1 flex items-center justify-center">
          <div className="text-center">
            <h1 className="text-2xl font-bold mb-4">Album non trouvé</h1>
            <Link href="/albums">
              <Button variant="primary">Retour aux albums</Button>
            </Link>
          </div>
        </main>
        <Footer />
      </div>
    );
  }

  const totalDuration = album.tracks.reduce((acc, track) => acc + track.duration, 0);

  const handlePlayAll = () => {
    setQueue(album.tracks, 0);
    play(album.tracks[0]);
  };

  // Albums similaires (même genre)
  const similarAlbums = mockAlbums
    .filter(
      (a) =>
        a.id !== album.id &&
        a.genres.some((g) => album.genres.includes(g))
    )
    .slice(0, 4);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-1 pb-24">
        {/* Back Link */}
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-4">
          <Link
            href="/albums"
            className="inline-flex items-center gap-2 text-[var(--color-gray-600)] hover:text-[var(--color-black)] transition-colors"
          >
            <ArrowLeft size={18} />
            Retour aux albums
          </Link>
        </div>

        {/* Album Header */}
        <section className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-8">
          <div className="flex flex-col md:flex-row gap-8">
            {/* Cover */}
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              className="w-full md:w-80 flex-shrink-0"
            >
              <Card padding="none" className="overflow-hidden aspect-square relative">
                <Image
                  src={album.cover}
                  alt={album.title}
                  fill
                  sizes="(max-width: 768px) 100vw, 320px"
                  className="object-cover"
                  priority
                />
              </Card>
            </motion.div>

            {/* Info */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className="flex-1"
            >
              <p className="text-sm font-medium text-[var(--color-primary)] mb-2">
                {album.label}
              </p>
              <h1 className="text-3xl md:text-4xl lg:text-5xl font-bold text-[var(--color-black)] mb-4">
                {album.title}
              </h1>
              <p className="text-[var(--color-gray-600)] mb-6 max-w-xl">
                {album.description}
              </p>

              {/* Meta */}
              <div className="flex flex-wrap items-center gap-4 text-sm text-[var(--color-gray-600)] mb-6">
                <span className="flex items-center gap-1">
                  <Music size={16} />
                  {album.trackCount} pistes
                </span>
                <span className="flex items-center gap-1">
                  <Clock size={16} />
                  {formatDuration(totalDuration)}
                </span>
                <span>
                  Sorti le {new Date(album.releaseDate).toLocaleDateString("fr-FR")}
                </span>
              </div>

              {/* Tags */}
              <div className="flex flex-wrap gap-2 mb-8">
                {album.genres.map((genre) => (
                  <Link key={genre} href={`/search?genre=${genre}`}>
                    <Tag variant="genre" clickable>
                      {genre}
                    </Tag>
                  </Link>
                ))}
                {album.moods.map((mood) => (
                  <Link key={mood} href={`/search?mood=${mood}`}>
                    <Tag variant="mood" clickable>
                      {mood}
                    </Tag>
                  </Link>
                ))}
              </div>

              {/* Actions */}
              <div className="flex flex-wrap gap-3">
                <Button variant="primary" size="lg" onClick={handlePlayAll}>
                  <Play size={20} className="mr-2 fill-white" />
                  Tout écouter
                </Button>
                <Button variant="outline" size="lg">
                  <Heart size={20} className="mr-2" />
                  Favoris
                </Button>
                <Button variant="ghost" size="lg">
                  <Share2 size={20} />
                </Button>
              </div>
            </motion.div>
          </div>
        </section>

        {/* Tracks */}
        <section className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-8">
          <h2 className="text-xl font-bold text-[var(--color-black)] mb-6">
            Pistes
          </h2>
          <Card padding="none" className="divide-y divide-[var(--color-gray-100)]">
            {album.tracks.map((track, index) => (
              <TrackRow
                key={track.id}
                track={track}
                album={album}
                index={index}
                showAlbumCover={false}
              />
            ))}
          </Card>
        </section>

        {/* Similar Albums */}
        {similarAlbums.length > 0 && (
          <section className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-8">
            <h2 className="text-xl font-bold text-[var(--color-black)] mb-6">
              Albums similaires
            </h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6">
              {similarAlbums.map((similarAlbum, index) => (
                <motion.div
                  key={similarAlbum.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.1 }}
                >
                  <AlbumCard album={similarAlbum} />
                </motion.div>
              ))}
            </div>
          </section>
        )}
      </main>

      <Footer />
      <MiniPlayer />
    </div>
  );
}

"use client";

import { useState, useMemo, useCallback, Suspense } from "react";
import { useSearchParams } from "next/navigation";
import { motion } from "framer-motion";
import {
  Grid3X3,
  List,
  X,
  ChevronDown,
  ChevronUp,
  RotateCcw,
} from "lucide-react";
import { Header, Footer } from "@/components/layout";
import { Button, Tag, Card, Input } from "@/components/ui";
import { TrackRow, SearchBar, MiniPlayer } from "@/components/features";
import {
  getAllTracks,
  mockAlbums,
  GENRES,
  MOODS,
  INSTRUMENTS,
} from "@/lib/mock-data";
import { cn } from "@/lib/utils";
import type { ViewMode, Track } from "@/types";

function SearchContent() {
  const searchParams = useSearchParams();
  const initialQuery = searchParams.get("q") || "";
  const initialGenre = searchParams.get("genre") || "";
  const initialMood = searchParams.get("mood") || "";

  const [query, setQuery] = useState(initialQuery);
  const [viewMode, setViewMode] = useState<ViewMode>("list");
  const [showFilters, setShowFilters] = useState(true);

  // Filter states
  const [selectedGenres, setSelectedGenres] = useState<string[]>(
    initialGenre ? [initialGenre] : []
  );
  const [selectedMoods, setSelectedMoods] = useState<string[]>(
    initialMood ? [initialMood] : []
  );
  const [selectedInstruments, setSelectedInstruments] = useState<string[]>([]);
  const [bpmRange, setBpmRange] = useState<[number, number]>([60, 180]);
  const [durationRange, setDurationRange] = useState<[number, number]>([0, 300]);
  const [isVocal, setIsVocal] = useState<boolean | null>(null);

  // Collapsed sections
  const [collapsedSections, setCollapsedSections] = useState<Set<string>>(
    new Set()
  );

  const toggleSection = (section: string) => {
    setCollapsedSections((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(section)) {
        newSet.delete(section);
      } else {
        newSet.add(section);
      }
      return newSet;
    });
  };

  const allTracks = getAllTracks();

  const filteredTracks = useMemo(() => {
    return allTracks.filter((track) => {
      // Text search
      if (query) {
        const lowerQuery = query.toLowerCase();
        const album = mockAlbums.find((a) => a.id === track.albumId);
        const matchesTitle = track.title.toLowerCase().includes(lowerQuery);
        const matchesAlbum = album?.title.toLowerCase().includes(lowerQuery);
        const matchesGenre = track.genres.some((g) =>
          g.toLowerCase().includes(lowerQuery)
        );
        const matchesMood = track.moods.some((m) =>
          m.toLowerCase().includes(lowerQuery)
        );
        if (!matchesTitle && !matchesAlbum && !matchesGenre && !matchesMood) {
          return false;
        }
      }

      // Genres
      if (
        selectedGenres.length > 0 &&
        !selectedGenres.some((g) => track.genres.includes(g))
      ) {
        return false;
      }

      // Moods
      if (
        selectedMoods.length > 0 &&
        !selectedMoods.some((m) => track.moods.includes(m))
      ) {
        return false;
      }

      // Instruments
      if (
        selectedInstruments.length > 0 &&
        !selectedInstruments.some((i) => track.instruments.includes(i))
      ) {
        return false;
      }

      // BPM
      if (track.bpm < bpmRange[0] || track.bpm > bpmRange[1]) {
        return false;
      }

      // Duration
      if (track.duration < durationRange[0] || track.duration > durationRange[1]) {
        return false;
      }

      // Vocal
      if (isVocal !== null && track.isVocal !== isVocal) {
        return false;
      }

      return true;
    });
  }, [
    allTracks,
    query,
    selectedGenres,
    selectedMoods,
    selectedInstruments,
    bpmRange,
    durationRange,
    isVocal,
  ]);

  const resetFilters = useCallback(() => {
    setQuery("");
    setSelectedGenres([]);
    setSelectedMoods([]);
    setSelectedInstruments([]);
    setBpmRange([60, 180]);
    setDurationRange([0, 300]);
    setIsVocal(null);
  }, []);

  const hasActiveFilters =
    query ||
    selectedGenres.length > 0 ||
    selectedMoods.length > 0 ||
    selectedInstruments.length > 0 ||
    bpmRange[0] !== 60 ||
    bpmRange[1] !== 180 ||
    durationRange[0] !== 0 ||
    durationRange[1] !== 300 ||
    isVocal !== null;

  const toggleArrayFilter = (
    arr: string[],
    setArr: (arr: string[]) => void,
    value: string
  ) => {
    if (arr.includes(value)) {
      setArr(arr.filter((v) => v !== value));
    } else {
      setArr([...arr, value]);
    }
  };

  const FilterSection = ({
    title,
    id,
    children,
  }: {
    title: string;
    id: string;
    children: React.ReactNode;
  }) => {
    const isCollapsed = collapsedSections.has(id);
    return (
      <div className="border-b border-[var(--color-gray-100)] pb-4">
        <button
          onClick={() => toggleSection(id)}
          className="flex items-center justify-between w-full py-2 text-left"
        >
          <span className="font-semibold text-[var(--color-black)]">{title}</span>
          {isCollapsed ? <ChevronDown size={18} /> : <ChevronUp size={18} />}
        </button>
        {!isCollapsed && <div className="mt-2">{children}</div>}
      </div>
    );
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-1 pb-24">
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-8">
          {/* Search Bar */}
          <div className="mb-8">
            <SearchBar
              defaultValue={query}
              onSearch={setQuery}
              placeholder="Rechercher par titre, genre, mood..."
            />
          </div>

          <div className="flex flex-col lg:flex-row gap-8">
            {/* Filters Sidebar */}
            <aside
              className={cn(
                "lg:w-72 flex-shrink-0",
                showFilters ? "block" : "hidden lg:block"
              )}
            >
              <Card padding="md" hover={false}>
                <div className="flex items-center justify-between mb-4">
                  <h2 className="font-bold text-[var(--color-black)]">Filtres</h2>
                  {hasActiveFilters && (
                    <button
                      onClick={resetFilters}
                      className="text-sm text-[var(--color-primary)] hover:underline flex items-center gap-1"
                    >
                      <RotateCcw size={14} />
                      Réinitialiser
                    </button>
                  )}
                </div>

                <div className="space-y-4">
                  {/* Genres */}
                  <FilterSection title="Genres" id="genres">
                    <div className="flex flex-wrap gap-2">
                      {GENRES.map((genre) => (
                        <Tag
                          key={genre}
                          variant={
                            selectedGenres.includes(genre) ? "genre" : "default"
                          }
                          size="sm"
                          clickable
                          onClick={() =>
                            toggleArrayFilter(
                              selectedGenres,
                              setSelectedGenres,
                              genre
                            )
                          }
                        >
                          {genre}
                          {selectedGenres.includes(genre) && (
                            <X size={12} className="ml-1" />
                          )}
                        </Tag>
                      ))}
                    </div>
                  </FilterSection>

                  {/* Moods */}
                  <FilterSection title="Moods" id="moods">
                    <div className="flex flex-wrap gap-2">
                      {MOODS.map((mood) => (
                        <Tag
                          key={mood}
                          variant={
                            selectedMoods.includes(mood) ? "mood" : "default"
                          }
                          size="sm"
                          clickable
                          onClick={() =>
                            toggleArrayFilter(
                              selectedMoods,
                              setSelectedMoods,
                              mood
                            )
                          }
                        >
                          {mood}
                          {selectedMoods.includes(mood) && (
                            <X size={12} className="ml-1" />
                          )}
                        </Tag>
                      ))}
                    </div>
                  </FilterSection>

                  {/* Instruments */}
                  <FilterSection title="Instruments" id="instruments">
                    <div className="flex flex-wrap gap-2">
                      {INSTRUMENTS.map((instrument) => (
                        <Tag
                          key={instrument}
                          variant={
                            selectedInstruments.includes(instrument)
                              ? "instrument"
                              : "default"
                          }
                          size="sm"
                          clickable
                          onClick={() =>
                            toggleArrayFilter(
                              selectedInstruments,
                              setSelectedInstruments,
                              instrument
                            )
                          }
                        >
                          {instrument}
                          {selectedInstruments.includes(instrument) && (
                            <X size={12} className="ml-1" />
                          )}
                        </Tag>
                      ))}
                    </div>
                  </FilterSection>

                  {/* BPM Range */}
                  <FilterSection title="Tempo (BPM)" id="bpm">
                    <div className="space-y-2">
                      <div className="flex items-center gap-2">
                        <Input
                          type="number"
                          value={bpmRange[0]}
                          onChange={(e) =>
                            setBpmRange([parseInt(e.target.value) || 60, bpmRange[1]])
                          }
                          className="w-20 text-sm py-1 px-2"
                          min={60}
                          max={180}
                        />
                        <span className="text-[var(--color-gray-400)]">-</span>
                        <Input
                          type="number"
                          value={bpmRange[1]}
                          onChange={(e) =>
                            setBpmRange([bpmRange[0], parseInt(e.target.value) || 180])
                          }
                          className="w-20 text-sm py-1 px-2"
                          min={60}
                          max={180}
                        />
                      </div>
                    </div>
                  </FilterSection>

                  {/* Vocal/Instrumental */}
                  <FilterSection title="Type" id="vocal">
                    <div className="flex gap-2">
                      <Tag
                        variant={isVocal === null ? "primary" : "default"}
                        size="sm"
                        clickable
                        onClick={() => setIsVocal(null)}
                      >
                        Tous
                      </Tag>
                      <Tag
                        variant={isVocal === true ? "primary" : "default"}
                        size="sm"
                        clickable
                        onClick={() => setIsVocal(true)}
                      >
                        Vocal
                      </Tag>
                      <Tag
                        variant={isVocal === false ? "primary" : "default"}
                        size="sm"
                        clickable
                        onClick={() => setIsVocal(false)}
                      >
                        Instrumental
                      </Tag>
                    </div>
                  </FilterSection>
                </div>
              </Card>
            </aside>

            {/* Results */}
            <div className="flex-1">
              {/* Results Header */}
              <div className="flex items-center justify-between mb-4">
                <p className="text-[var(--color-gray-600)]">
                  <span className="font-semibold text-[var(--color-black)]">
                    {filteredTracks.length}
                  </span>{" "}
                  résultats
                </p>

                <div className="flex items-center gap-3">
                  {/* Mobile Filter Toggle */}
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setShowFilters(!showFilters)}
                    className="lg:hidden"
                  >
                    Filtres
                  </Button>

                  {/* View Toggle */}
                  <div className="flex border-2 border-[var(--color-black)] rounded-[var(--radius-sm)] overflow-hidden">
                    <button
                      onClick={() => setViewMode("list")}
                      className={cn(
                        "p-2 transition-colors",
                        viewMode === "list"
                          ? "bg-[var(--color-black)] text-white"
                          : "bg-white text-[var(--color-black)] hover:bg-[var(--color-gray-100)]"
                      )}
                    >
                      <List size={18} />
                    </button>
                    <button
                      onClick={() => setViewMode("grid")}
                      className={cn(
                        "p-2 transition-colors border-l-2 border-[var(--color-black)]",
                        viewMode === "grid"
                          ? "bg-[var(--color-black)] text-white"
                          : "bg-white text-[var(--color-black)] hover:bg-[var(--color-gray-100)]"
                      )}
                    >
                      <Grid3X3 size={18} />
                    </button>
                  </div>
                </div>
              </div>

              {/* Active Filters */}
              {hasActiveFilters && (
                <div className="flex flex-wrap gap-2 mb-4">
                  {selectedGenres.map((genre) => (
                    <Tag
                      key={genre}
                      variant="genre"
                      size="sm"
                      clickable
                      onClick={() =>
                        setSelectedGenres(selectedGenres.filter((g) => g !== genre))
                      }
                    >
                      {genre}
                      <X size={12} className="ml-1" />
                    </Tag>
                  ))}
                  {selectedMoods.map((mood) => (
                    <Tag
                      key={mood}
                      variant="mood"
                      size="sm"
                      clickable
                      onClick={() =>
                        setSelectedMoods(selectedMoods.filter((m) => m !== mood))
                      }
                    >
                      {mood}
                      <X size={12} className="ml-1" />
                    </Tag>
                  ))}
                </div>
              )}

              {/* Track List */}
              {filteredTracks.length > 0 ? (
                <Card padding="none" hover={false}>
                  {filteredTracks.slice(0, 50).map((track, index) => {
                    const album = mockAlbums.find((a) => a.id === track.albumId);
                    return (
                      <TrackRow
                        key={track.id}
                        track={track}
                        album={album}
                        index={index}
                        showAlbumCover={true}
                      />
                    );
                  })}
                </Card>
              ) : (
                <div className="text-center py-16">
                  <p className="text-[var(--color-gray-600)] text-lg mb-4">
                    Aucune piste trouvée avec ces critères.
                  </p>
                  <Button variant="outline" onClick={resetFilters}>
                    Réinitialiser les filtres
                  </Button>
                </div>
              )}

              {filteredTracks.length > 50 && (
                <p className="text-center text-[var(--color-gray-400)] mt-4">
                  Affichage des 50 premiers résultats sur {filteredTracks.length}
                </p>
              )}
            </div>
          </div>
        </div>
      </main>

      <Footer />
      <MiniPlayer />
    </div>
  );
}

export default function SearchPage() {
  return (
    <Suspense fallback={<div>Chargement...</div>}>
      <SearchContent />
    </Suspense>
  );
}

